window.__saqPaperQuestions("2023-2-pah",[{"number":1,"title":"","stemText":"A 66 year old woman has presented with a 2 day history of cough, shortness of breath and fever. Her chest x-ray is provided below.","parts":[{"id":"a","label":"Part A","prompt":"Provide 4 radiographic abnormalities. (4 marks)"},{"id":"b","label":"Part B","prompt":"List 4 features of your assessment that would confer a raised likelihood of requiring\nintensive respiratory or vasopressor support as per either the CORB or SMART-COP risk stratification tools. (4 marks) Your assessment is consistent with severe pneumonia."},{"id":"c","label":"Part C","prompt":"State your antibiotic therapy, including the intended anti-microbial coverage. (4 marks)"}],"propPages":["asset:imge68bce5e38b0a5f847","asset:img91038b47346c5741be"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">air bronchograms</div><div class=\"answer-line\">Patchy LLL opacification</div><div class=\"answer-line\">Obscuration of L heart border</div><div class=\"answer-line\">Partial obscuration of L hemidiaphragm</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Multilobar involvement on CXR</div><div class=\"answer-line\">Albumin &lt; 35 g/L</div><div class=\"answer-line\">RR &gt;30</div><div class=\"answer-line\">HR &gt;125</div><div class=\"answer-line\">New confusion</div><div class=\"answer-line\">PaO2 &lt;60mmHg or SaO2 &lt;90%</div><div class=\"answer-line\">pH &lt;7.35</div><div class=\"answer-line\">SBP &lt;90mmHg or DBP &lt;60mmHg</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">2g IV ceftriaxone - strep pneumoniae/haemophilus influenzae</div><div class=\"answer-line\">500mg IV azithromycin - mycoplasma/chlamydia/legionella</div><div class=\"answer-line\">Would accept pip/taz instead of ceftriaxone</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"An 8 year old boy has presented with bleeding 7 days after a tonsillectomy.\nOn examination, he has active brisk bleeding from his pharynx with the following vital signs:\n\nHR\n140 /min\n\nBP\n90/40 mmHg O2 sats 97% room air\n\nWeight\nkg","parts":[{"id":"a","label":"Part A","prompt":"State 4 strategies that could be employed in the ED to control the haemorrhage. (4 marks)\nDespite your initial management, the patient continues to bleed and will require intubation to protect his airway."},{"id":"b","label":"Part B","prompt":"Complete the following table regarding airway equipment for this patient. (3 marks) ETT size ETT depth of insertion LMA size"},{"id":"c","label":"Part C","prompt":"List 4 difficulties you would anticipate during the intubation, including your management\n• f each. (4 marks)\nDifficulty Management"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Topical co-phenylcaine</div><div class=\"answer-line\">Hydrogen Peroxide Mouthwash</div><div class=\"answer-line\">15mg/kg IV TXA</div><div class=\"answer-line\">0.3mcg/kg IV DDAVP</div><div class=\"answer-line\">Direct pressure with adrenaline soaked gauze</div><div class=\"answer-line\">Suction visible blood and clot</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">ETT depth = age/2 + 12 = 16 cm</div><div class=\"answer-line\">LMA size = 25 kg = size 3</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Positioning – maintain upright/ sitting forward until induction administered, then 30deg</div><div class=\"answer-line\">Pre-oxygenation with active bleeding – position upright, HFNP O2 at FiO2 1.0, 15L NRBM,</div><div class=\"answer-line\">self-suctioning</div><div class=\"answer-line\">Obscuration of cord view with clot – suction, direct laryngoscopy</div><div class=\"answer-line\">Blood aspiration – pre-oxygenation with PEEP, dual suction</div><div class=\"answer-line\">Hypotension on induction – ketamine for induction 1mg/kg, fluid load 10mLs/kg IV n.saline</div><div class=\"answer-line\">or 10mL/kg PRBC targeting SBP&gt;90</div><div class=\"answer-line\">Increased tonsillar bed haemorrhage – direct pressure with adrenaline soaked gauze</div><div class=\"answer-line\">Fear/agitation – parental reassurance</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 24 year old man has presented after falling 3 metres on to his left foot from some scaffolding at work. An x-ray of his foot is provided below.","parts":[{"id":"a","label":"Part A","prompt":"Provide the diagnosis with 2 supportive radiographic abnormalities. (3 marks)"},{"id":"b","label":"Part B","prompt":"List 4 commonly associated injuries from this mechanism. (4 marks)\nThere are no other injuries on examination."},{"id":"c","label":"Part C","prompt":"State 4 components of your management. (4 marks)"}],"propPages":["asset:imga47bbe3603ce1413f7"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Calcaneal fracture</div><div class=\"answer-line\">Decreased Bohler’s angle &lt;20 degrees</div><div class=\"answer-line\">Fracture line / lucency through body of calcaneus</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Lumbar vertebral fractures</div><div class=\"answer-line\">Cervical spine fractures</div><div class=\"answer-line\">Tibial plateau fracture</div><div class=\"answer-line\">Pelvic fractures (ie vertical shear)</div><div class=\"answer-line\">Additional foot fractures – talar, cuboid (ie pilon fracture)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia – something reasonable ie parenteral opiates or oral opiates</div><div class=\"answer-line\">Immobilise in short leg back slab – well-padded heel</div><div class=\"answer-line\">Elevate leg, non-weight bear</div><div class=\"answer-line\">Orthopaedic referral for operative management (likely as outpatient if isolated)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 52 year old man has been brought to the ED after a hanging.\nThe ambulance crew found him in a PEA arrest. ROSC was achieved after 10 minutes of ALS. He was intubated at the scene. Soon after arrival to the ED, a chest x-ray was performed. It is provided below.","parts":[{"id":"a","label":"Part A","prompt":"State the most likely pathology demonstrated, with 3 supportive radiographic abnormalities. (4 marks)\nHis vital signs are as follows:\n\nGCS\n\nHR\n105 /min\n\nBP\n88/54 mmHg O2 sats 89%\n\nFiO2 1.0"},{"id":"b","label":"Part B","prompt":"State 2 treatment measures you would institute. Include end-points. (2 marks)"},{"id":"c","label":"Part C","prompt":"Apart from the pathology shown above, list 4 potential complications of this presentation. For each, state a supportive finding on examination. (4 marks) Complication Examination finding Shortly after arrival, the patient’s ventilator has begun to display a high pressure alarm."},{"id":"d","label":"Part D","prompt":"List 3 possible causes for the alarm. For each, give your management. (3 marks)\nCause Management The patient’s family have arrived."},{"id":"e","label":"Part E","prompt":"State 5 key components of your discussion with the family. (5 marks)"}],"propPages":["asset:img02ffb2734547add382","asset:imge1d74f016769c04e35"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Neurogenic pulmonary oedema</div><div class=\"answer-line\">R sided widespread patchy opacification</div><div class=\"answer-line\">L upper zone patchy opacification</div><div class=\"answer-line\">Kerley B lines</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">10mcg/min IV noradrenaline aiming SBP &gt;90 (accept Adrenaline)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Severe hypoxic brain injury – fixed dilated pupils GCS 3 , myoclonus</td><td>Carotid dissection – bruit on auscultation, stroke syndrome if not GCS 3 ie hemiparesis</td></tr><tr><td>Horners syndrome – unilateral small pupil</td><td>Spinal cord injury – no anal tone</td></tr><tr><td>Flail segment from CPR – mobile segment on palpation</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Tension pneumothorax</strong> – finger thoracostomy and ICC</td><td>Ventilator dysynchrony – commence sedation, re-paralyse</td></tr><tr><td>Worsening pulmonary oedema – increase PEEP and accept higher pressure limits</td><td>Tube obstruction – suction in-line (blood/secretions)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Update on events so far</div><div class=\"answer-line\">Discuss poor prognosis given &gt; 10 mins downtime, remaining GCS 3</div><div class=\"answer-line\">Provide social support – ED social worker, pastoral care</div><div class=\"answer-line\">Ascertain significant life limiting co-morbidities – end stage organ disease, terminal cancer</div><div class=\"answer-line\">Discuss pre-morbid functional capacity and quality of life</div><div class=\"answer-line\">Discuss trajectory from ED – ICU cares, neurological testing, guarded prognosis</div><div class=\"answer-line\">Obtain further information that may aid care – comorbidities, allergies, medications ie</div><div class=\"answer-line\">(anticoagulants)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 32 week pregnant woman has arrived in labour and rapidly delivered her baby in the emergency department. The umbilical cord has been cut and tied and the baby has been given to you for management.","parts":[{"id":"a","label":"Part A","prompt":"State 2 actions you might perform in the first minute. Provide the indication for each.\n(2 marks) Action Indication"},{"id":"b","label":"Part B","prompt":"State 5 further treatment measures you might institute. Provide the indication for each.\n(5 marks) Treatment Indication"},{"id":"c","label":"Part C","prompt":"List 5 components of the APGAR scoring system. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Warm and vigorously dry – poor tone and not crying</td><td>Commence PPV – poor resp effort, apnoeic, HR &lt;100</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Intubation – prolonged CPR, no spont resp effort</td><td>Oropharyngeal suctioning – where meconium/other FB in oral caviting impairing</td></tr><tr><td>ventilation/oxygenation</td><td>IV adrenaline 10mcg/kg – HR &lt;60 despite cycle of CPR</td></tr><tr><td>IV glucose 2mL/kg 10% – BSL &lt; 3 (accept 2-5mls/kg 10%)</td><td>100% oxygen – if CPR required or if pre-ductal sats &lt;85% at 10 mins</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">A – appearance (skin colour)</div><div class=\"answer-line\">P – pulse</div><div class=\"answer-line\">G – grimace (reflex irritability)</div><div class=\"answer-line\">A – activity (tone)</div><div class=\"answer-line\">R – respirations</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 5 year old boy has been carried to triage by his parents with active tonic-clonic seizure activity.","parts":[{"id":"a","label":"Part A","prompt":"State 6 features of your history that will impact your management, with rationale for each. (6 marks) History Rationale"},{"id":"b","label":"Part B","prompt":"List 4 complications of prolonged seizure activity and provide a strategy to mitigate each in this child. (4 marks) Complication Mitigation strategy"},{"id":"c","label":"Part C","prompt":"List 4 indications for endotracheal intubation in this child. (4 marks)\nDespite 2 doses of IV midazolam, the child has ongoing seizure activity."},{"id":"d","label":"Part D","prompt":"List 4 medications you might administer. Provide the clinical circumstances for when you\nwould administer each. (4 marks) Medication Clinical circumstances"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Known epilepsy – usual management plan, current AEs</td><td>Time of seizure onset – give midazolam 0.2mg/kg IV/buccal if &gt; 5mins</td></tr><tr><td>Number of seizures – immediate midazolam 0.2mg/kg IV/buccal plus levetiracetam 60mg/kg</td><td>IV if in status epilepticus</td></tr><tr><td>Head trauma – immediate seizure termination and neuroprotective measures</td><td>Fever – IV ceftriaxone 50mg/kg and IV dexamethasone 0.3mg/kg for meningoencephalitis</td></tr><tr><td>cover</td><td>T1DM – IV glucose 2mLs/kg 10%</td></tr><tr><td>Known toxicological ingestion – treat as appropriate</td><td>Known space occupying lesion – keppra and dexamethasone</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Hypoxia – opening airway, administration of passive oxygenation, sats probe</div><div class=\"answer-line\">Resp acidosis – assisted ventilation if patient hypoventilating</div><div class=\"answer-line\">Heat injury from hypermetabolism – aggressive management of seizure with benzos</div><div class=\"answer-line\">Tongue biting/ oral trauma from maceration – use of bite-blocks/OP airway to avoid oral</div><div class=\"answer-line\">closure</div><div class=\"answer-line\">Fractures/soft tissue injury from either falls or forced extension – soft bed/rails etc</div><div class=\"answer-line\">Rhabdomyolysis – use of benzos/ other muscle relaxants as needed</div><div class=\"answer-line\">Other answers ie arrythmias, resp failure etc will need to be qualified</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Refractory hypoxia</div><div class=\"answer-line\">Recurrent vomiting/upper airway obstruction</div><div class=\"answer-line\">Refractory bleeding from oral trauma leading to aspiration</div><div class=\"answer-line\">Persistent hypercapnoea</div><div class=\"answer-line\">Others probably ok</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Second line anticonvulsant (accept leviteracetam/ phenobarbitone/ valproate with</div><div class=\"answer-line\">appropriate doses) - for ongoing generalised seizure activity &gt;10mins duration</div><div class=\"answer-line\">Antibiotics – if clinical concern for CNS infection ie preceeding fever/confusion/</div><div class=\"answer-line\">immunosuppression – ie ceftriaxone 50mg/kg or cefotaxime 50mg/kg</div><div class=\"answer-line\">IV dextrose – 2-5ml/kg 10% dextrose if demonstrable hypoglycaemia (ie BSL &lt;3)</div><div class=\"answer-line\">IV dexamethasone 0.15mg/kg to 10mg if known intracranial mass</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 63 year old alcoholic female has presented with generalised abdominal pain, nausea and vomiting following recent heavy alcohol consumption. Her venous blood gas is provided below. Venous blood gas Reference range\n\npH\n7.14 (7.35 - 7.45)\n\npCO2\nmmHg (35 - 45)\n\nHCO3\nmmol/L (20 - 28)\n\nNa\n145 mmol/L (135 - 145)\n\nK\n5.5 mmol/L (3.5 - 4.5)\n\nCl\nmmol/L (88 - 108)\n\nLactate\n2.6 mmol/L (<2.0)\n\nGlucose\n3.2 mmol/L (3.0 - 5.5)\n\nHb\n140 g/L (110 - 140)","parts":[{"id":"a","label":"Part A","prompt":"Identify the metabolic acid-base abnormalities present. Provide the calculations for each. Include the most likely cause. (6 marks) Acid-base abnormality Calculations Most likely cause"},{"id":"b","label":"Part B","prompt":"List 3 additional blood tests you would perform that would give diagnostic clarification.\nProvide rationale for each. (3 marks) Test Rationale On examination, the patient is confused. She has a soft abdomen with mild generalised tenderness but no peritonism. There are no features of sepsis.\nHer vital signs are:\n\nGCS\nE4 V4 M6 Temperature 36.5 degrees Pulse 120 /min\n\nBP\n85/55 mmHg\n\nRR\n/min"},{"id":"c","label":"Part C","prompt":"State 3 steps in your initial management of this patient. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>AG =  Na – (Cl + HCO3)</td><td>Ketoacids (not Lactate – only mildly</td></tr><tr><td><strong>(AG – 36</strong>)</td><td>= 145 - (98 + 11) raised) - could also be toxic alcohol</td></tr><tr><td>= 36</td><td>ingestion or renal failure)</td></tr><tr><td>Comorbid</td><td>Metabolic Delta Gap = delta AG/ delta HCO3 Acid loss from vomiting</td></tr><tr><td>Alkalosis</td><td>=  24/ 13</td></tr><tr><td>= approx 2</td><td></td></tr><tr><td>2.</td><td></td></tr><tr><td><strong>Ketones – confirm ketoacidosis </strong></td><td></td></tr><tr><td>Lipase – cause for vomiting (pancreatitis)</td><td></td></tr><tr><td>LFTs – may indicate obstructive hepatopathy as cause for abdominal pain</td><td></td></tr><tr><td>Accept osmolarity – looking for osmolar gap to exclude toxic alcohol ingestion</td><td></td></tr><tr><td>Renal function – cause of HAGMA</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Acid-base abnormality</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Thiamine or Pabrinex 300mg IV or 2amps IV</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 72 year old man has presented with severe chest pain.\nA slice from a CT scan of his chest is provided below.","parts":[{"id":"a","label":"Part A","prompt":"Interpret the image. (3 marks)"},{"id":"b","label":"Part B","prompt":"Apart from what is demonstrated above, list 4 potential complications of this diagnosis. State a key examination finding you would expect for each. (4 marks) Complication Examination finding\nHis vital signs are:\n\nGCS\nPulse 110 /min\n\nBP\n190/120 mmHg"},{"id":"c","label":"Part C","prompt":"State 4 components of your management of this patient. (4 marks)"}],"propPages":["asset:imga811c67f3667e52ad3"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Haemopericardium</div><div class=\"answer-line\">Dissection flap in descending aorta</div><div class=\"answer-line\"><strong>IMP: Standford A aortic dissection </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Aortic Valve Incompetence</td><td>Branch vessel dissection – Stroke</td></tr><tr><td>Branch Vessel dissection – Spinal Injury with acute paralysis</td><td>Branch Vessel dissection – Focal Ischaemia – renal/splenic/mesenteric etc</td></tr><tr><td>Branch vessel dissection – limb ischaemia</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia – IV opiates to comfort</div><div class=\"answer-line\">B-blockers to achieve HR 60 – IV metoprolol 1mg repeats</div><div class=\"answer-line\">Additional BP control – ie hydralazine 10mg boluses to achieve BP &lt;120</div><div class=\"answer-line\">(Doses / routes for all)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"You are drafting a journal article submission following the completion of a single blinded, parallel group randomised controlled trial (RCT) in your department.","parts":[{"id":"a","label":"Part A","prompt":"Provide a definition of a single blinded, parallel group RCT. (3 marks)"},{"id":"b","label":"Part B","prompt":"State 6 components of your abstract as defined by the CONSORT abstract guidelines.\n(6 marks)"},{"id":"c","label":"Part C","prompt":"State 3 limitations of RCTs. (3 marks)\nPAH 2023.2 trial SAQ paper\nPART 2\nQuestions 10 - 18\n1 hour"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Single blinded = patients do not know which treatment they are on (ie A/B or placebo/trial)</div><div class=\"answer-line\">Parallel Group = Two groups of patients, each assigned a different treatment.</div><div class=\"answer-line\">RCT = Study groups are randomised at enrolment to control for variables outside direct experimental</div><div class=\"answer-line\">control</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Title</div><div class=\"answer-line\">Authors</div><div class=\"answer-line\">Tiral Dsign</div><div class=\"answer-line\">Methods</div><div class=\"answer-line\">Results</div><div class=\"answer-line\">Conclusion</div><div class=\"answer-line\"><em>Trial Registration </em></div><div class=\"answer-line\"><em>Funding </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Underpowering</div><div class=\"answer-line\">May underrepresent harms</div><div class=\"answer-line\">Enrolment challenges</div><div class=\"answer-line\">Costly</div><div class=\"answer-line\">Slow to collect ie practice may move on</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 42 year old woman has been referred to the ED by her LMO with hyperthyroidism.","parts":[{"id":"a","label":"Part A","prompt":"State FOUR features on assessment that would be consistent with thyroid storm. (4 marks) Your assessment is consistent with thyroid storm."},{"id":"b","label":"Part B","prompt":"In the following table, list FOUR medications you might use to manage this patient’s thyroid storm. For each, state the mechanism through which this may help manage the acute situation. (8 marks) Medication Mechanism"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Fever</div><div class=\"answer-line\">Tachy &gt;130</div><div class=\"answer-line\">CHF</div><div class=\"answer-line\">GIT dysfunction</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Hydrocortisone – 100mg q6h prevents peripheral T4 to T3</td><td><strong>Propranolol </strong>(or other beta blocker) – 40-80mg q4h prevents symptoms of catecholamine</td></tr><tr><td>overactivity, decreased T4 to T3</td><td>Iodine – 5 drops q6h inhibits new hormone production</td></tr><tr><td>PTU – 500 – 1000mg inhibits thyroid hormone synthesis, decreased T4 to T3</td><td>Bile Acid Sequestration – Cholestyramine 4gm QID – decrease enterohepatic circulation thyroid</td></tr><tr><td>hormone</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 70 year old man has collapsed at the shops with chest pain.\nThe ambulance service found him to be pale and confused with a heart rate of 35/min. They have commenced transcutaneous pacing. He has not received any other treatments. His rhythm strip on arrival to ED is provided below.","parts":[{"id":"a","label":"Part A","prompt":"Interpret the rhythm strip. (3 marks)\nHis vital signs are:\n\nGCS\nE4 V4 M6\n\nBP\n80/40 mmHg O2 sats 99% 15L O2 via non-rebreather mask He has poor peripheral perfusion."},{"id":"b","label":"Part B","prompt":"State 4 potential actions you might employ to increase his blood pressure. (4 marks)\nYour actions have restored adequate perfusion and blood pressure."},{"id":"c","label":"Part C","prompt":"State 4 features of your history that will impact management. Include your rationale.\n(4 marks) The ambulance officer has shown you the limited ECG taken when they initially arrived at the scene. It is provided below."},{"id":"d","label":"Part D","prompt":"Interpret the ECG and state the supportive ECG findings. (4 marks)"},{"id":"e","label":"Part E","prompt":"State the 3 most important components of your further management. (3 marks)"}],"propPages":["asset:img507e0be48142c7c812","asset:img2122b0c1141b71a830"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Regular pacing spikes rate 80/min</div><div class=\"answer-line\">Paced beats with broad complex ventrcular activity</div><div class=\"answer-line\">Pacing spikes without ventricular capture</div><div class=\"answer-line\"><strong>Failure to capture  </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Increase pacing current</strong> to 10mA above Amperage required to achieve 1:1 capture</div><div class=\"answer-line\">Ensure pads in sufficient contact with skin to exclude contact issues</div><div class=\"answer-line\">IV fluid load 10-20ml/kg</div><div class=\"answer-line\">Atropine 600mcg IV</div><div class=\"answer-line\">Chemical pacing – isoprenaline 1-20mcg/min or adrenaline 5-30mcg/min</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Preceding chest pain – may need reperfusion</div><div class=\"answer-line\">Known renal disease – may need urgent hyperkalaemic Rx ie calcium therapy</div><div class=\"answer-line\">Medications – AV blocking agents (CCBs/ B-blockers)</div><div class=\"answer-line\">Head strike – will require CT head before any antiplatelets/anticoagulants</div><div class=\"answer-line\">Life-limiting comorbidities or dementia – not for PPM insertion if indicated post assessment</div><div class=\"answer-line\">Others...</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Regular P waves approx 60/min</div><div class=\"answer-line\">Regular narrow QRS complexes approx 38/min</div><div class=\"answer-line\">STE III &gt; II</div><div class=\"answer-line\">ST depression I</div><div class=\"answer-line\">IMP: <strong>Acute inferior STEMI with third degree AV block and junctional escape rhythm </strong></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Analgesia – IV morphine 2.5mg repeat to comfort OR heparin bolus with dose</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 21 year old man has been brought to the ED after being stabbed to the right side of his chest. His chest x-ray is provided below.","parts":[{"id":"a","label":"Part A","prompt":"State 4 abnormalities seen on the chest x-ray. (4 marks)"},{"id":"b","label":"Part B","prompt":"List 4 other investigations you might perform. Provide the clinical utility of each.\n(4 marks) Assessment reveals no extra-thoracic injuries."},{"id":"c","label":"Part C","prompt":"State 3 indications for operative management of this patient. (3 marks)"}],"propPages":["asset:img7ac8dbd82ab9ef353a","asset:imgd776f3d0f2ade1dfb0","asset:imgb0dfac19d4cc543932"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Veiled opacification Rt hemithorax</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Rim of blood around lung edge</div><div class=\"answer-line\">Subcutaneous emphysema Rt chest wall indicating pneumothorax</div><div class=\"answer-line\">Mediastinal shift to left indicating radiologic tension</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">CT Angio thorax – define bleeding focus and determine suitability for interventions</div><div class=\"answer-line\">CT Thorax – concurrent spinal injury</div><div class=\"answer-line\">Blood Gas – for type II resp failure or metabolic status – may indicate need for intubation or</div><div class=\"answer-line\">transfusion</div><div class=\"answer-line\">X-match – to make blood available for transfusion</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Ongoing massive air-leak or recurrent tension</div><div class=\"answer-line\">Massive haemorrhage &gt;1500mls or &gt;200mls/hr for 4+ hours</div><div class=\"answer-line\">Oesophageal injury</div><div class=\"answer-line\">Heart injury / pericardial tamponade</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 4 year old girl has been brought to the ED by her parents. She has had a rash for the last 24 hours. A photograph is provided below.","parts":[{"id":"a","label":"Part A","prompt":"State your diagnosis, with 3 supportive features present in the photo. (4 marks)"},{"id":"b","label":"Part B","prompt":"List 3 infectious aetiologies that could be responsible for the rash. (3 marks)"},{"id":"c","label":"Part C","prompt":"List 3 non-infectious aetiologies that could be responsible for the rash. (3 marks)\nYou have concluded that there has been a non-infectious cause for this child’s presentation and are satisfied the child is suitable for discharge."},{"id":"d","label":"Part D","prompt":"State two key aspects of your advice regarding treatment. (2 marks)"}],"propPages":["asset:img50c3c9427996061a24","asset:img8ddacf0fa9333cc4bc"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Multiple discrete, well demarcated lesions</div><div class=\"answer-line\">Erythematous appearance</div><div class=\"answer-line\">VARYING size</div><div class=\"answer-line\">Central sparing</div><div class=\"answer-line\">Diagnosis: Erythema Multiforme</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Mycoplasma pneumoniae (now reclassified as MIRM ie not EM)</div><div class=\"answer-line\">Herpes Simplex</div><div class=\"answer-line\">CMV</div><div class=\"answer-line\">EBV</div><div class=\"answer-line\">Influenza</div><div class=\"answer-line\">COVID</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Antibiotics (Erythromycin, Nitrofurantoin, Penicillins, Sulfonamides, tetracyclines)</div><div class=\"answer-line\">Anticonvulsants</div><div class=\"answer-line\">NSAIDs</div><div class=\"answer-line\">Vaccinations</div><div class=\"answer-line\">IBD</div><div class=\"answer-line\">Hepatitis C</div><div class=\"answer-line\">Malignancy (Lymphoma, Leukaemia)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Likely self-limiting with treatment focused on underlying cause</div><div class=\"answer-line\">Symptomatic treatments ok (antihistamines, simple oral analgesics)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 42 year old man with known autosomal dominant Polycystic Kidney Disease (PCKD) has presented to the ED with flank pain.","parts":[{"id":"a","label":"Part A","prompt":"List 5 differential diagnoses for his pain that relate to his underlying disease. For each, provide a confirmatory finding on assessment (history, examination or investigation). (10 marks) Differential Diagnosis Assessment finding"},{"id":"b","label":"Part B","prompt":"List 3 extra-renal conditions associated with AD-PCKD. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Cyst infection – fever dysuria</td><td>Cyst haemorrhage– haematuria, hypotension</td></tr><tr><td>Cyst rupture – free fluid on CT – intra or retro peritoneal</td><td>Renal calculi (nephrocalcinosis or ureteric colic) - haematuria, loin-to-groin pain</td></tr><tr><td>Renal capsule stretch from mass effect – early satiety, abdominal fullness</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Cysts in other organs (liver, pancreas, seminal vesicles)</div><div class=\"answer-line\">Berry Aneurysms</div><div class=\"answer-line\">Aortic Root dilatation</div><div class=\"answer-line\">Mitral Valve prolapse</div><div class=\"answer-line\">Abdominal wall hernias</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 65 year old woman has been found on the floor of her home by a neighbour. She had not been seen for the previous 24 hours. The ambulance team report the patient’s temperature to be 27 degrees Celsius.","parts":[{"id":"a","label":"Part A","prompt":"List 5 examination findings that you would anticipate given her hypothermia. (5 marks)\nOn transfer to the ED trolley, the patient develops ventricular fibrillation."},{"id":"b","label":"Part B","prompt":"State 5 factors, with explanation, you would consider in the management of this situation. (5 marks) Return of spontaneous circulation was achieved after a brief period of advanced life support."},{"id":"c","label":"Part C","prompt":"List 4 options for re-warming the patient. (4 marks)"},{"id":"d","label":"Part D","prompt":"List 4 further investigations you would perform. Provide justification for each. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Bradycardia</div><div class=\"answer-line\">Bradypnoea</div><div class=\"answer-line\">Hypotension</div><div class=\"answer-line\">Fixed dilated pupils</div><div class=\"answer-line\">Areflexia</div><div class=\"answer-line\">Pulmonary oedema</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Commence CPR 30:2</strong> with minimal interruptions – key focus for successful resuscitation</div><div class=\"answer-line\"><strong>Single defibrillation attempt</strong> – likely to not work until T&gt;30 deg and should not interrupt CPR</div><div class=\"answer-line\">Administer adrenaline 1gm after unsuccessful shock and then repeat q4min to 3 doses max until</div><div class=\"answer-line\">T&gt;30</div><div class=\"answer-line\">Minimise unnecessary handling as can precipitate further arrest</div><div class=\"answer-line\">Aggressive warming with warm blankets (not precluding CPR), BAIR hugger and 40deg saline</div><div class=\"answer-line\">20mls/kg (accept warmed bladder irrigation also)</div><div class=\"answer-line\">ECMO an option for rewarming arrested pt</div><div class=\"answer-line\">ALS to continue until pt warmed or obviously dead</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Warm IV fluids</div><div class=\"answer-line\">Warmed forced air</div><div class=\"answer-line\">Warm bladder lavage</div><div class=\"answer-line\">Thoracic or peritoneal lavage</div><div class=\"answer-line\">(ECMO not correct – ROSC)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Serum K – likely dangerously elevated – rhabdo, due to metabolic acidosis from hypoperfusion</td><td>ECG – looking for cause of fall (arrhythmia, MI) or slow AF of hypothermia</td></tr><tr><td>VBG – define degree of hypoperfusion – lactic acidosis</td><td>BSL – cause or consequence of long time on floor – require immediate Rx</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 45 year old man has been brought to the ED after a motor vehicle accident.\nA slice from a sagittal CT reconstruction of his lumbar spine is shown below.","parts":[{"id":"a","label":"Part A","prompt":"Describe the abnormality shown. (3 marks) He is complaining of leg weakness."},{"id":"b","label":"Part B","prompt":"Complete the table by stating the key muscle group for each spinal level as per the International Standards for Neurological Classification of Spinal Cord Injury. (5 marks) Spinal level Key muscle group L2 L3 L4 L5 S1"},{"id":"c","label":"Part C","prompt":"List 3 other injuries often associated with this type of injury. (3 marks)"}],"propPages":["asset:imgdffc587fd80b35db6a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Anterior compression with loss of height</div><div class=\"answer-line\">Posterior distraction with posterior elements fractured</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>L2 – hip flexion</td><td>L3 – knee extension</td></tr><tr><td>L4 – ankle dorsiflexion</td><td>L5 – great toe dorsiflexion</td></tr><tr><td>S1 – ankle plantarflexion</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Pancreatic contusion/laceration</div><div class=\"answer-line\">Duodenal injury – contusion / perforation</div><div class=\"answer-line\">Aortic injury</div><div class=\"answer-line\">Mesenteric injury</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 12 month old boy has been brought to hospital with fever and a widespread rash.\nA clinical photograph is provided below.","parts":[{"id":"a","label":"Part A","prompt":"List 4 descriptive features of the rash. (4 marks)"},{"id":"b","label":"Part B","prompt":"State the most likely diagnosis. (1 mark)"},{"id":"c","label":"Part C","prompt":"State the 2 main components of your initial management. (2 marks)"},{"id":"d","label":"Part D","prompt":"List 4 laboratory investigations you would perform. Provide justification for each.\n(4 marks)"}],"propPages":["asset:img3d30c750a419376dbf"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Widespread – thorax, left arm, head/face</div><div class=\"answer-line\">Petchiae</div><div class=\"answer-line\">Purpura</div><div class=\"answer-line\">Purple colour</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Meningococcal sepsis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">IV N/S 20ml/kg bolus</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>BSL – hypoglycaemia due to sepsis will require Rx</td><td>BC – aim to confirm infection and Ab sensitivities for rationalisation Rx</td></tr><tr><td>VBG – define degree of hypoperfusion – lactic acidosis</td><td>Meningococcal PCR – urgent to confirm Dx – target Rx, public health issues/prophylaxis</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 4 year old girl has been brought to the ED after ingesting an unknown amount of her\ngrandmother’s diltiazem.","parts":[{"id":"a","label":"Part A","prompt":"State 6 treatment measures you might institute, including doses where appropriate.\nProvide the clinical circumstance where each treatment is indicated. (12 marks) Treatment measure Clinical circumstance\nPAH 2023.2 trial SAQ paper\nPART 3\nQuestions 19 - 27\n1 hour"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Charcoal po or NG 1g/kg</td><td>all pts with life threatening ingestion</td></tr><tr><td>Whole bowel irrigation PEG 25ml/kg/hr po or NG</td><td>life threatening SR ingestion</td></tr><tr><td>IV N/S 20ml/kg</td><td>first line for hypotension</td></tr><tr><td>CaCl2 10% 0.2mL/kg</td><td>for all pts with hypotension – aim ionised Ca &gt;1.5</td></tr><tr><td>Adrenaline infusion start 0.1mcg/kg/min</td><td>where hypotension exists after fluid/Ca</td></tr><tr><td colspan=\"2\">particularly if there is bradycardia and decreased contractility on echo</td></tr><tr><td>HIET insulin 1U/kg with dextrose 50ml 50%</td><td>ongoing hypotension despite adrenaline with</td></tr><tr><td colspan=\"2\">decreased contractility on echo</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 45 year old woman has presented with palpitations for the last 12 hours.\nHer ECG shows a narrow complex tachycardia at a rate of 150 beats per minute.","parts":[{"id":"a","label":"Part A","prompt":"State 4 different rhythms that might be causing this tachycardia. For each, list a\ndiscriminatory feature from the ECG that would support its presence. (8 marks) Rhythm Discriminatory ECG feature Her ECG is provided below."},{"id":"b","label":"Part B","prompt":"State the rhythm shown. (1 mark)"},{"id":"c","label":"Part C","prompt":"List 3 medications you might use including the clinical justification for each. (3 marks)"}],"propPages":["asset:img71c8b76b1d8d55d5ad"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Sinus rhythm – variability with respiration / posture / IV fluid / activity</td><td>Atrial fibrillation – irregularly irregular rhythm</td></tr><tr><td>Atrial flutter – regular, flutter waves present</td><td>AVNRT – regular, no P waves (or retrograde)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Atrial flutter</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Medication</th><th>Justification</th></tr></thead><tbody><tr><td>Flecainide 2mg/kg IV – aiming for cardioversion where risk of thromboembolism is low (ie not</td><td>recurrent problem)</td></tr><tr><td>Digoxin 500mcg IV  first load – for rate control where beta-blockers contra-indicated eg APO</td><td>Metoprolol 25 - 50mg oral – aiming for rate control where no C/I – no CCF, robust BP</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 20 year old woman has presented with a self-inflicted wound to her right anterior forearm. A clinical photo is presented below.","parts":[{"id":"a","label":"Part A","prompt":"List 4 structures that might be injured. For each, state a cardinal examination finding.\n(8 marks) Structure Examination finding"},{"id":"b","label":"Part B","prompt":"State 4 components of your management of this injury. (4 marks)"}],"propPages":["asset:img71362ed3c7e79c32f4"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Radial artery</strong> – pale hand, loss of pulse distal to wound</td><td>Median nerve – loss sensation thenar eminence palm, loss thumb abduction</td></tr><tr><td>FDS – loss inability to flex fingers at PIPJ (when other fingers are held straight)</td><td>FCR – weakness wrist flexion with radial deviation (abduction)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Analgesia – anything really with dose/route</div><div class=\"answer-line\">IV Abs – Kefzol 1g</div><div class=\"answer-line\">Wash and dress wound under LA</div><div class=\"answer-line\">Ensure ADT up to date</div><div class=\"answer-line\">Ortho admission for operative management</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 6 month old boy has been brought to the ED with difficulty breathing and\nwheeze. Your provisional diagnosis is bronchiolitis.","parts":[{"id":"a","label":"Part A","prompt":"List 3 differential diagnoses. Provide a discriminatory examination finding for each.\n(3 marks) Differential diagnosis Discriminatory examination finding You are confident that the child has bronchiolitis."},{"id":"b","label":"Part B","prompt":"List 5 features of your history or examination that would suggest admission is warranted.\n(5 marks) Following your assessment and a period of observation, you have decided that the patient is suitable for discharge."},{"id":"c","label":"Part C","prompt":"State 4 features of your discharge discussion with the patient’s parents. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>CCF – murmurs, hepatomegaly, peripheral oedema</td><td>Bacterial pneumonia – focal findings on chest auscultation / asymmetrical</td></tr><tr><td>Foreign body or food aspiration  – unilateral chest hyperexpansion, unilateral findings (wheeze,</td><td>reduced BS)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Inability to feed – (&lt;50% usual)</div><div class=\"answer-line\">Hypoxia – sats &lt;90% room air</div><div class=\"answer-line\">Pre-existing medical condition eg congenital heart disease</div><div class=\"answer-line\">Apnoeic episodes</div><div class=\"answer-line\">Other signs severe disease – significant use accessory muscles, marked increased RR,</div><div class=\"answer-line\">irritability/fatigue</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Education of disease – common, no specific Rx</div><div class=\"answer-line\">Likely course – 7-10 days</div><div class=\"answer-line\">When to come back – feeding, work of breathing</div><div class=\"answer-line\">Assess parent’s ability to return to hospital</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 60 year old man has presented to the ED with shortness of breath. His chest x-ray has revealed a large right sided unilateral pleural effusion. You intend to perform pleurocentesis as part of your management.","parts":[{"id":"a","label":"Part A","prompt":"List 5 potential complications of the insertion of a small bore drainage catheter. For each, state the safety measure you will adopt to avoid its occurrence. (5 marks) Complication Safety measure The following results are available after venesection and pleurocentesis: Pleural fluid LDH 336 U/L Protein g/L Serum LDH 346 U/L (120 - 250) Protein g/L (60 - 80)"},{"id":"b","label":"Part B","prompt":"Interpret the results. (3 marks)"},{"id":"c","label":"Part C","prompt":"List 3 possible causes for this pleural effusion. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Infection (cellulitis/empyema) – sterile technique</td><td>Pneumothorax – perform under USS guidance to avoid lung injury</td></tr><tr><td>Abdominal organ injury (liver) – perform in triangle of safety, use USS to confirm position</td><td>Intercostal neurovascular bundle injury – enter above rib not below</td></tr><tr><td>Accidental catheter dislodgment – ensure well sutured to skin</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Exudate</div><div class=\"answer-line\">Pleural:serum LDH &gt;0.6</div><div class=\"answer-line\">Pleural:serum protein &gt;0.5</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Pneumonia</div><div class=\"answer-line\">Pulmonary embolism</div><div class=\"answer-line\">Malignancy</div><div class=\"answer-line\">Autoimmune – Rheumatoid, SLE</div><div class=\"answer-line\">Haemothorax, Chylothorax</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 23 year old woman has been brought to the ED with bizarre behaviour.\nShe was found by police walking around the streets with her 4 week old baby, screaming “there are snakes in my head, get them out”.\nShe is 4 weeks post-partum.","parts":[{"id":"a","label":"Part A","prompt":"State 6 features of your history and examination of this woman. Include the clinical\nrelevance. (6 marks) You have assessed the patient as having a psychosis that requires inpatient management."},{"id":"b","label":"Part B","prompt":"List 4 investigations you might perform, with justification. (4 marks)"},{"id":"c","label":"Part C","prompt":"State 4 components of your assessment of the child. Include the relevance of each.\n(4 marks)"},{"id":"d","label":"Part D","prompt":"State 3 options for the ongoing care of the child. Include the circumstances where each\n• ption would be appropriate. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Vital signs</strong> – exclude serious causes of delirium eg  sepsis</div><div class=\"answer-line\">Hx drug use – eg meth – cause of psychosis</div><div class=\"answer-line\">Hx MH disorder eg schizophrenia likely to be causing psychosis</div><div class=\"answer-line\">Specific features of post-partum psychosis – regarding safety of child ie thoughts of harm to child</div><div class=\"answer-line\">Hx regarding child’s care – feeding, bathing, clothing etc</div><div class=\"answer-line\">PMHx/ medications that might cause delirium eg anti-cholinergics</div><div class=\"answer-line\">Many others</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">CT head – perform if first episode psychosis to exclude SOL as cause</div><div class=\"answer-line\">Chem 20 – exclude electrolyte problem causing altered mental state eg hyponatraemia</div><div class=\"answer-line\">Septic screen – urine M/C/S, CXR if focal symptoms or signs of infection causing delirium</div><div class=\"answer-line\">Urine drug screen – confirm/exclude amphetamine use as cause psychosis</div><div class=\"answer-line\">Will be others</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Vital signs – looking for significant dehydration resulting from neglect</div><div class=\"answer-line\">Weight – compare with birth weight to assess adequacy of feeding / neglect</div><div class=\"answer-line\">Signs of trauma or neglect – resulting from harm / abuse due to mother’s psychosis</div><div class=\"answer-line\">BSL – hypoglycaemia from lack of feeding</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Admit with mother – where no alternate option for care and mother has been looking after baby</div><div class=\"answer-line\">well and no concerns for deliberate harm</div><div class=\"answer-line\">Home with alternate family – where supportive family exists, child can be bottle fed, mother not</div><div class=\"answer-line\">able to care for child</div><div class=\"answer-line\">Emergency foster care – child unable to be with mother due to care concerns, no alternate family</div><div class=\"answer-line\">options</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 5 year old boy has been brought to the ED with right arm pain after falling off a swing set at daycare. His x-ray is provided below.","parts":[{"id":"a","label":"Part A","prompt":"Describe the injury shown. (3 marks)"},{"id":"b","label":"Part B","prompt":"List 4 potential early complications of this injury. (4 marks)\nThere is a wound over the dorsal surface of the proximal forearm. There are no other injuries."},{"id":"c","label":"Part C","prompt":"State 3 options for analgesia, including doses. (3 marks)"},{"id":"d","label":"Part D","prompt":"Apart from analgesia, state 5 components of your management of the patient. (5 marks) Following the administration of one of medications, the patient has developed a wheeze and urticarial rash, consistent with anaphylaxis. The patient has the following vital signs: Alert Pulse 160 /min\n\nBP\n75/35 mmHg O2 sats 89% room air"},{"id":"e","label":"Part E","prompt":"State 3 components of your initial management. (3 marks)"}],"propPages":["asset:img951c4819d777e7e512","asset:imgdc86b6ea709017ca00"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Monteggia fracture/dislocation</div><div class=\"answer-line\">Proximal ulnar fracture, angulated</div><div class=\"answer-line\">Proximal radial head dislocation anteriorly</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Median nerve injury</div><div class=\"answer-line\">Compartment syndrome</div><div class=\"answer-line\">Another nerve – radial, ulnar</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">IV morphine 0.1mg/kg</div><div class=\"answer-line\">IN fentanyl 1.5mcg/kg</div><div class=\"answer-line\">Oral paracetamol 15mg/kg, ibuprofen 10mg/kg, oxycodone 0.1-0.2mg/kg</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Procedural sedation – ketamine 0.5mg/kg</div><div class=\"answer-line\">Wash wound</div><div class=\"answer-line\">Plaster long arm</div><div class=\"answer-line\">(accept attempted reduction or not)</div><div class=\"answer-line\">Orthopaedic referral for washout and ORIF</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">IM adrenaline 10mcg/kg</div><div class=\"answer-line\">O2 via Hudson mask aim sats &gt;90%</div><div class=\"answer-line\">IV N/S 20ml/kg</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"At the morning handover, one of the night shift registrars has complained to you about the excessive number of night shifts they have worked, resulting in them feeling “burnt out” and unable to keep working.","parts":[{"id":"a","label":"Part A","prompt":"State 6 key features of your management of this situation. (6 marks)\nFollowing this incident, you have been placed in charge of rostering for the trainees."},{"id":"b","label":"Part B","prompt":"State 6 considerations when writing a roster. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Arrange discussion in private setting</div><div class=\"answer-line\">Find out what registrar is experiencing (listen to story)</div><div class=\"answer-line\">Is there a safety concern for registrar eg depression / self-harm</div><div class=\"answer-line\">Investigate number night shifts / equality</div><div class=\"answer-line\">Notify director / roster co-ordinator</div><div class=\"answer-line\">Arrange follow up for registrar - ?rest from nights / GP / psychologist depending on problem</div><div class=\"answer-line\">Arrange follow up meeting with trainee – yourself / mentor / DEMT depending on preference</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Contractual requirements eg number of nights / hours per week / days off</div><div class=\"answer-line\">Number of shifts required to be filled</div><div class=\"answer-line\">Number FTE trainees</div><div class=\"answer-line\">Leave requests</div><div class=\"answer-line\">On call allocations for sick leave</div><div class=\"answer-line\">Specific roster requests around examinations / training requirements</div><div class=\"answer-line\">Equitable roster allocation nights / weekends / evenings</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"An 80 year old woman has presented with abdominal pain and distension.\nShe has a history of ischaemic heart disease, hypertension and severe dementia. Her abdominal x-ray is provided below.","parts":[{"id":"a","label":"Part A","prompt":"Describe the x-ray, including the likely diagnosis. (3 marks)"},{"id":"b","label":"Part B","prompt":"List 4 further investigations you might perform with justification for each. (4 marks)"},{"id":"c","label":"Part C","prompt":"State 5 considerations when considering whether invasive management is appropriate for\nthis patient. (5 marks)"}],"propPages":["asset:img40967c850071023fca","asset:imgd7bbd00a33f0aa3b95"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Caecal or sigmoid volvulus – would accept both</div><div class=\"answer-line\">Dilated large bowel</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Haustra</div><div class=\"answer-line\">No air in rectum</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>VBG – assess for lactic acidosis as marker of ischaemic bowel</td><td>Electrolytes – exclude hypokalaemia, hypomagnesaemia due to third space losses</td></tr><tr><td>CT abdomen – exclude obstructing malignancy, cause of volvulus, perforation</td><td>G&amp;H or coags – in case of operative intervention</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Volvulus is amenable to surgical repair – no large malignancy or large segment of ischaemic gut</div><div class=\"answer-line\">Less invasive options available – rectal tube decompression</div><div class=\"answer-line\">Patient’s wishes, documented AHD</div><div class=\"answer-line\">Functional status</div><div class=\"answer-line\">Life limiting co-morbidities</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 45 year old man has presented with a fever, headache and confusion.\nHe has a background of HIV, although he does not take any medications. On examination, he has right sided weakness.","parts":[{"id":"a","label":"Part A","prompt":"List 4 potential causes of his symptoms. (4 marks)"},{"id":"b","label":"Part B","prompt":"List 4 investigations you might perform, with justification. (4 marks)\nYour junior medical officer has sustained a needlestick injury while managing the patient."},{"id":"c","label":"Part C","prompt":"List 4 factors that would increase the risk of HIV transmission. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Cerebral abscess</strong> from opportunistic infection – toxoplasmosis, cryptococcus</div><div class=\"answer-line\">CNS lymphoma</div><div class=\"answer-line\">Progressive multifocal leukoencephalopathy</div><div class=\"answer-line\">CMV encephalopathy</div><div class=\"answer-line\">Aneurysmal subarachnoid haemorrhage</div><div class=\"answer-line\">Post-ictal with Todd’s paresis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>CT head</strong> noncon – exclude ICH</div><div class=\"answer-line\">CT head with contrast – abscess/SOL</div><div class=\"answer-line\">CSF – cell count, gram stain and cytology to exclude infection/malignancy</div><div class=\"answer-line\"><strong>CD4 count</strong> – &lt;200 AIDs at high risk of opportunistic infections/AIDs defining illnesses</div><div class=\"answer-line\">Viral load – determine HIV status degree of immunocompromise</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">High viral load from source patient / Source patient non-compliant with antiviral medications</div><div class=\"answer-line\">Large bore needle with visible blood soiling</div><div class=\"answer-line\">Needle stick directly into vein or artery</div><div class=\"answer-line\">Skin breach, not wearing gloves</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
